   folder=out/z.team;folder.mkdir(exist_ok=True);base=source/'networks'/z.team;pf=base/'present_passing_matrix.csv';af=base/'absent_passing_matrix.csv';Pframe=pd.read_csv(pf,index_col=0);Aframe=pd.read_csv(af,index_col=0);ids=Pframe.index.astype(int).tolist();assert ids==Pframe.columns.astype(int).tolist()==Aframe.index.astype(int).tolist()==Aframe.columns.astype(int).tolist();P=Pframe.to_numpy(float);A=Aframe.to_numpy(float);hub=ids.index(z.star_id);D=P.copy();D[hub]=0;D[:,hub]=0;assert A[hub].sum()+A[:,hub].sum()==0 and (D>=0).all() and A.sum()>0 and D.sum()>0;den=np.log2(active_n(P+A)-1);hp,hd,ha=[float(bits(M))/den for M in [P,D,A]];q,r=norm(D),norm(A);si,sa=involvement(D),involvement(A);edge_tv=float(abs(q-r).sum()/2);node_tv=float(abs(si-sa).sum()/2);js=float(jensenshannon(q.ravel(),r.ravel(),base=2)**2);common=(D.sum(1)>0)&(A.sum(1)>0);w=(q.sum(1)+r.sum(1))[common];w=w/w.sum();conditional_js=float(sum(weight*jensenshannon(norm(D[i]),norm(A[i]),base=2)**2 for i,weight in zip(np.flatnonzero(common),w)))
