   counts=P.astype(int);original_draw=rng.multivariate_hypergeometric(counts.ravel(),N,size=a.draws).reshape(a.draws,*counts.shape);original_sample=bits(original_draw)/den;matched_pred=float((sample[0]-original_sample).mean());matched_actual=float((sample[1]-original_sample).mean())
