   for i,pid in enumerate(ids):nodes.append(dict(team=z.team,player_id=pid,player_name=names.get(pid,str(pid)),is_star=i==hub,original_involvement_share=involvement(P)[i],deleted_involvement_share=si[i],actual_involvement_share=sa[i],actual_minus_deleted_share=sa[i]-si[i],original_node_area=16000*involvement(P)[i],deleted_node_area=16000*si[i],actual_node_area=16000*sa[i]))
